    """Return a compact multi-leaf Merkle inclusion proof for one height.

    POST /v1/blocks/{height}/multiproof with ``{"tx_ids": [...]}``. The
    body rules are exactly those of :meth:`get_proofs` (a JSON object
    with only ``tx_ids``: a non-empty list of distinct 64-lowercase-hex
    strings); any violation — including a JSON parse failure — is 400 and
    never touches state. The height must be a non-negative ASCII decimal
    without leading zeros; a malformed/unknown height or any requested
    transaction absent from the block is 404 (the whole batch fails,
    never a partial proof), and a pending block is 409.

    On success the document carries only ``height``, ``block_hash``,
    ``merkle_root``, ``leaf_count``, ``leaves`` and ``nodes``:
    ``leaf_count`` is the block's true leaf count, ``leaves`` holds one
    ``{tx_id, index}`` item per requested transaction ordered by block
    index, and ``nodes`` holds the shared sibling subtree roots (see
    :func:`ledger.crypto.merkle_multiproof`). The response depends only
    on the requested id set, never on request order.
    """
    if not isinstance(payload, dict) or set(payload) != {"tx_ids"}:
        return 400, {"error": "request body must be a JSON object with only 'tx_ids'"}
    tx_ids_raw = payload["tx_ids"]
    if not isinstance(tx_ids_raw, list) or not tx_ids_raw:
        return 400, {"error": "field 'tx_ids' must be a non-empty array"}
    if any(not crypto.is_hex64(tx_id) for tx_id in tx_ids_raw):
        return 400, {
            "error": "every tx_id must be a string of 64 lowercase hex characters"
        }
    if len(set(tx_ids_raw)) != len(tx_ids_raw):
        return 400, {"error": "tx_ids must be distinct"}

    height_int = _parse_height_decimal(height)
    if height_int is None:
        return 404, {"error": "block not found"}
    with self.store.lock:
        block = self.store.block_at(height_int)
        if block is None:
            return 404, {"error": "block not found"}
        if block.status != STATUS_CONFIRMED:
            return 409, {"error": "block is pending confirmation"}
